{
  "type": "object",
  "properties": {
    "roles": {
      "type": "array",
      "description": "One entry for each kind of person the client asks for",
      "items": {
        "type": "object",
        "properties": {
          "role": { "type": "string", "description": "Job title, for example React Native Developer" },
          "skills": { "type": "array", "items": { "type": "string" }, "description": "Skills this person needs, in lowercase" },
          "seniority": { "type": "string", "enum": ["junior", "mid", "senior", "lead", "any"] },
          "count": { "type": "number", "description": "How many people for this role" }
        },
        "required": ["role", "skills", "seniority", "count"]
      }
    },
    "durationMonths": { "type": "number", "description": "How long the team is needed, in months" },
    "startDate": { "type": "string", "description": "When the work should start, as YYYY-MM-DD" },
    "budget": { "type": "number", "description": "Monthly budget in US dollars" },
    "industry": { "type": "string", "description": "The client's industry in one or two lowercase words, for example fintech" },
    "notes": { "type": "string", "description": "Any other condition that matters for choosing the team" }
  },
  "required": ["roles"]
}

parameters.jsCode:
// Tidy up what the AI extracted, so the next steps can rely on its shape
const extracted = $input.first().json.output || {};
const request = $('Webhook').first().json.body;

const roles = (extracted.roles || []).map((role) => ({
  role: role.role,
  skills: (role.skills || []).map((skill) => String(skill).toLowerCase().trim()),
  seniority: role.seniority || 'any',
  count: role.count || 1,
}));

return [
  {
    json: {
      requestId: request.requestId,
      parsed: {
        roles,
        durationMonths: extracted.durationMonths ?? null,
        startDate: extracted.startDate ?? null,
        budget: extracted.budget ?? null,
        industry: extracted.industry ?? null,
        notes: extracted.notes ?? '',
      },
    },
  },
];

// Turn each role into one availability search: which skill, from which date, to which date
const { requestId, parsed } = $input.first().json;

// Start date: what the client said, or today if they did not say
const today = new Date().toISOString().slice(0, 10);
const from = parsed.startDate || today;

// End date: start date plus the number of months (6 if the client did not say)
const months = parsed.durationMonths || 6;
const toDate = new Date(from);
toDate.setUTCMonth(toDate.getUTCMonth() + months);
const to = toDate.toISOString().slice(0, 10);

// One item per role, so the next node runs once for each role
return parsed.roles.map((role) => ({
  json: {
    requestId,
    role: role.role,
    skill: role.skills[0] || '',
    seniority: role.seniority,
    count: role.count,
    from,
    to,
  },
}));

// Put each developer back under the role they were searched for
const requirement = $('Clean Requirement').first().json;
const searches = $('Prepare Search').all().map((item) => item.json);
const developers = $input.all().map((item) => item.json);

const roles = searches.map((search) => {
  const seen = new Set();

  // Developers who have this role's skill, each one only once
  const candidates = developers.filter((dev) => {
    const hasSkill = !search.skill || dev.skills.some((skill) => skill.name === search.skill);
    if (!hasSkill || seen.has(dev._id)) return false;
    seen.add(dev._id);
    return true;
  });

  return {
    role: search.role,
    skill: search.skill,
    seniority: search.seniority,
    count: search.count,
    candidates: candidates.map((dev) => ({
      id: dev._id,
      name: dev.name,
      title: dev.title,
      seniority: dev.seniority,
      hourlyRate: dev.hourlyRate,
      freePercent: dev.freePercent,
      availableFrom: dev.availableFrom,
    })),
  };
});

return [
  {
    json: {
      requestId: requirement.requestId,
      parsed: requirement.parsed,
      from: searches[0]?.from,
      to: searches[0]?.to,
      roles,
    },
  },
];

// Give every candidate a match score out of 100, using simple rules we can explain
const data = $input.first().json;
const ONE_DAY = 24 * 60 * 60 * 1000;
const levels = ['junior', 'mid', 'senior', 'lead'];

// Up to 70 points: free for the whole period gets the most
function availabilityScore(candidate) {
  if (candidate.freePercent === 100) return 70;
  if (candidate.freePercent > 0) return Math.round((70 * candidate.freePercent) / 100);
  // Busy now: lose 1 point for every day they are late
  const daysLate = Math.ceil((new Date(candidate.availableFrom) - new Date(data.from)) / ONE_DAY);
  return Math.max(0, 70 - daysLate);
}

// Up to 30 points: how well the seniority fits what the client asked for
function seniorityScore(candidate, wanted) {
  if (wanted === 'any') {
    return { junior: 12, mid: 22, senior: 30, lead: 30 }[candidate.seniority] ?? 15;
  }
  const gap = Math.abs(levels.indexOf(candidate.seniority) - levels.indexOf(wanted));
  if (gap === 0) return 30;
  if (gap === 1) return 15;
  return 0;
}

const roles = data.roles.map((role) => ({
  ...role,
  candidates: role.candidates
    .map((candidate) => ({
      ...candidate,
      matchScore: availabilityScore(candidate) + seniorityScore(candidate, role.seniority),
    }))
    .sort((a, b) => b.matchScore - a.matchScore),
}));

return [{ json: { ...data, roles } }];

