{
  "type": "object",
  "properties": {
    "options": {
      "type": "array",
      "description": "2 or 3 different team options, best first",
      "items": {
        "type": "object",
        "properties": {
          "label": { "type": "string", "description": "Short name, for example Best match or Lowest cost" },
          "summary": { "type": "string", "description": "One sentence on what makes this option different" },
          "members": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "id": { "type": "string", "description": "The candidate id, copied exactly" },
                "role": { "type": "string" },
                "reason": { "type": "string", "description": "One sentence on why this person was picked" }
              },
              "required": ["id", "role", "reason"]
            }
          }
        },
        "required": ["label", "summary", "members"]
      }
    },
    "gaps": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Problems the client should know about"
    }
  },
  "required": ["options", "gaps"]
}

parameters.jsCode:
// Turn the Team Lead's picks into the final proposal.
// Names, scores and cost come from our own data, not from the AI.
const data = $('Score Candidates').first().json;
const teamLead = $input.first().json.output || {};
const HOURS_PER_MONTH = 160;
const budget = data.parsed.budget;

// Every candidate by id, so each pick can be looked up
const candidatesById = {};
for (const role of data.roles) {
  for (const candidate of role.candidates) {
    candidatesById[candidate.id] = candidate;
  }
}

const options = (teamLead.options || []).map((option) => {
  // Keep only people who really are in our candidate list
  const members = (option.members || [])
    .filter((member) => candidatesById[member.id])
    .map((member) => {
      const candidate = candidatesById[member.id];
      return {
        developer: candidate.id,
        name: candidate.name,
        title: candidate.title,
        role: member.role,
        matchScore: candidate.matchScore,
        reason: member.reason,
        availableFrom: candidate.availableFrom,
        hourlyRate: candidate.hourlyRate,
      };
    });

  const estimatedCost = members.reduce((total, member) => total + member.hourlyRate * HOURS_PER_MONTH, 0);
  const gaps = [...(teamLead.gaps || [])];
  if (budget && estimatedCost > budget) {
    gaps.push(`This team costs about $${estimatedCost.toLocaleString('en-US')} per month, above the $${budget.toLocaleString('en-US')} budget.`);
  }

  return { label: option.label, summary: option.summary, members, estimatedCost, gaps };
});

return [{ json: { requestId: data.requestId, parsed: data.parsed, options } }];
